e","Masa lambası","Sarı kalem","Kapı"],"correctAnswer":"B","questionType":"spatial","displayOrder":1},{"id":"f91d7168-eeed-5268-8b88-62b399fa7c20","questionText":"Deniz lambayı açtıktan hemen sonra ne yaptı?","options":["Kapıyı açtı","Sandalyeye oturdu","Defter nesnesini eline aldı","Pencereye doğru döndü"],"correctAnswer":"C","questionType":"sequence","displayOrder":2}]},{"id":"9e79c686-31be-5ffa-88f9-17a66a7bb8d5","exerciseId":"31aa34b2-0f98-56f0-a905-4e65dc297f75","description":"Ece, proje çalışma alanı içinde bir masanın önünde duruyor. Masanın üzerinde mavi bir dosya var. Bu nesnenin sağında bir beyaz kart, solunda ise küçük bir masa lambası bulunuyor. Pencere masanın arkasında, kapı odanın sol duvarında. Ece önce lambayı açıyor, sonra dosya nesnesini eline alıyor ve en son pencereye doğru dönüyor. Kapının yanındaki üç sandalyeden ortadakinin üzerinde bir mont var. Pencerenin karşısındaki rafta dört kitap ve bir kutu bulunuyor. Masanın altındaki sepet boş, duvardaki saatin altındaki pano ise iki afiş taşıyor.","duration":45,"displayOrder":1,"difficultyLevel":5,"targetAgeGroupId":"10000000-0000-0000-0000-000000000003","mode":"assessment","questions":[{"id":"65a0b8f6-e95f-5deb-a877-05c854f821d0","questionText":"Masadaki dosya hangi renkteydi?","options":["mor","mavi","yeşil","turuncu"],"correctAnswer":"B","questionType":"detail","displayOrder":0},{"id":"aa7303d8-25c3-5fe1-81cc-4a3247ffae8d","questionText":"Dosya nesnesinin solunda ne vardı?","options":["Kapı","Pencere","Masa lambası","Beyaz kart"],"correctAnswer":"C","questionType":"spatial","displayOrder":1},{"id":"b8f300b5-332c-57a3-a70f-9eb664d82ace","questionText":"Ece lambayı açtıktan hemen sonra ne yaptı?","options":["Pencereye doğru döndü","Kapıyı açtı","Sandalyeye oturdu","Dosya nesnesini eline aldı"],"correctAnswer":"D","questionType":"sequence","displayOrder":2}]},{"id":"f9c380fa-1abe-5e89-8e84-594b8a7e7735","exerciseId":"31aa34b2-0f98-56f0-a905-4e65dc297f75","description":"Mert, proje çalışma alanı içinde bir masanın önünde duruyor. Masanın üzerinde yeşil bir çanta var. Bu nesnenin sağında bir gri kutu, solunda ise küçük bir masa lambası bulunuyor. Pencere masanın arkasında, kapı odanın sol duvarında. Mert önce lambayı açıyor, sonra çanta nesnesini eline alıyor ve en son pencereye doğru dönüyor. Kapının yanındaki üç sandalyeden ortadakinin üzerinde bir mont var. Pencerenin karşısındaki rafta dört kitap ve bir kutu bulunuyor. Masanın altındaki sepet boş, duvardaki saatin altındaki pano ise iki afiş taşıyor.","duration":45,"displayOrder":2,"difficultyLevel":5,"targetAgeGroupId":"10000000-0000-0000-0000-000000000003","mode":"assessment","questions":[{"id":"81d0c4dd-1aaf-5934-ab56-c3fba5e36061","questionText":"Masadaki çanta hangi renkteydi?","options":["mor","kırmızı","yeşil","turuncu"],"correctAnswer":"C","questionType":"detail","displayOrder":0},{"id":"c9e29296-a87e-5a67-b77f-34f6f1776703","questionText":"Çanta nesnesinin solunda ne vardı?","options":["Gri kutu","Kapı","Pencere","Masa lambası"],"correctAnswer":"D","questionType":"spatial","displayOrder":1},{"id":"b36213bf-1e5c-5863-9ae9-10a1dce5e881","questionText":"Mert lambayı açtıktan hemen sonra ne yaptı?","options":["Çanta nesnesini eline aldı","Pencereye doğru döndü","Kapıyı açtı","Sandalyeye oturdu"],"correctAnswer":"A","questionType":"sequence","displayOrder":2}]}]$baseline$::jsonb) item;
DO $$ BEGIN
  IF (SELECT count(*) FROM visualization_payload)<>120
    OR (SELECT count(DISTINCT item->>'id') FROM visualization_payload)<>120
    OR (SELECT count(*) FROM visualization_baseline)<>60
    OR (SELECT count(DISTINCT item->>'id') FROM visualization_baseline)<>60
    THEN RAISE EXCEPTION 'Visualization payload incomplete'; END IF;
  IF (SELECT count(*) FROM visualization_payload p CROSS JOIN LATERAL jsonb_array_elements(p.item->'questions') q)<>360
    OR (SELECT count(DISTINCT q->>'id') FROM visualization_payload p CROSS JOIN LATERAL jsonb_array_elements(p.item->'questions') q)<>360
    THEN RAISE EXCEPTION 'Visualization question IDs incomplete or duplicated'; END IF;
  IF EXISTS(SELECT 1 FROM visualization_payload p LEFT JOIN speed_reading.exercises e
    ON e.id=(p.item->>'exerciseId')::uuid LEFT JOIN speed_reading.exercise_types t ON t.id=e.exercise_type_id
    WHERE e.id IS NULL OR e.is_deleted OR NOT e.is_active OR t.engine_type<>'visualization'
      OR e.difficulty_level<>(p.item->>'difficultyLevel')::int
      OR e.target_age_group_id IS DISTINCT FROM (p.item->>'targetAgeGroupId')::uuid)
    THEN RAISE EXCEPTION 'Visualization age/level exercise mismatch'; END IF;
  IF EXISTS(SELECT 1 FROM visualization_payload WHERE jsonb_array_length(item->'questions')<>3
    OR btrim(item->>'description')='' OR (item->>'duration')::int NOT BETWEEN 1 AND 3600)
    THEN RAISE EXCEPTION 'Visualization scene invalid'; END IF;
  IF EXISTS(SELECT 1 FROM visualization_payload p CROSS JOIN LATERAL jsonb_array_elements(p.item->'questions') q
    WHERE jsonb_typeof(q->'options') IS DISTINCT FROM 'array' OR jsonb_array_length(q->'options')<>4
      OR q->>'correctAnswer' NOT IN ('A','B','C','D')
      OR q->>'questionType' NOT IN ('detail','spatial','sequence')
      OR btrim(q->>'evidence')='' OR strpos(p.item->>'description',q->>'evidence')=0)
    THEN RAISE EXCEPTION 'Visualization answer/evidence mismatch'; END IF;
  IF EXISTS(SELECT 1 FROM visualization_baseline b LEFT JOIN speed_reading.visualization_scenes s
    ON s.id=(b.item->>'id')::uuid WHERE s.id IS NULL
      OR s.exercise_id<>(b.item->>'exerciseId')::uuid OR s.description IS DISTINCT FROM b.item->>'description'
      OR s.duration<>(b.item->>'duration')::int OR s.display_order<>(b.item->>'displayOrder')::int
      OR s.difficulty_level<>(b.item->>'difficultyLevel')::int
      OR s.target_age_group_id IS DISTINCT FROM (b.item->>'targetAgeGroupId')::uuid
      OR s.image_url IS DISTINCT FROM b.item->>'imageUrl' OR s.mode IS DISTINCT FROM b.item->>'mode')
    THEN RAISE EXCEPTION 'Visualization baseline edited or missing'; END IF;
  IF EXISTS(SELECT 1 FROM visualization_baseline b CROSS JOIN LATERAL jsonb_array_elements(b.item->'questions') q
    LEFT JOIN speed_reading.visualization_questions r ON r.id=(q->>'id')::uuid
    WHERE r.id IS NULL OR r.scene_id<>(b.item->>'id')::uuid OR r.is_deleted
      OR r.question_text IS DISTINCT FROM q->>'questionText' OR r.options_json IS DISTINCT FROM q->'options'
      OR (r.correct_answer IS DISTINCT FROM q->>'correctAnswer' AND r.correct_answer IS DISTINCT FROM
        (q->'options'->>(ascii(q->>'correctAnswer')-ascii('A'))))
      OR r.question_type IS DISTINCT FROM q->>'questionType' OR r.display_order<>(q->>'displayOrder')::int
      OR r.hint_text IS DISTINCT FROM q->>'hintText')
    THEN RAISE EXCEPTION 'Visualization baseline questions edited or missing'; END IF;
  IF EXISTS(SELECT 1 FROM visualization_baseline b JOIN speed_reading.visualization_questions r
    ON r.scene_id=(b.item->>'id')::uuid WHERE NOT r.is_deleted
      AND NOT EXISTS(SELECT 1 FROM jsonb_array_elements(b.item->'questions') q WHERE (q->>'id')::uuid=r.id))
    THEN RAISE EXCEPTION 'Visualization baseline has additional active questions'; END IF;
  IF EXISTS(SELECT 1 FROM visualization_payload p JOIN speed_reading.visualization_scenes s
    ON s.id=(p.item->>'id')::uuid WHERE s.exercise_id<>(p.item->>'exerciseId')::uuid
      OR s.description IS DISTINCT FROM p.item->>'description' OR s.duration<>(p.item->>'duration')::int
      OR s.display_order<>(p.item->>'displayOrder')::int OR s.difficulty_level<>(p.item->>'difficultyLevel')::int
      OR s.target_age_group_id IS DISTINCT FROM (p.item->>'targetAgeGroupId')::uuid
      OR s.mode<>'assessment' OR s.image_url IS NOT NULL OR s.is_deleted)
    THEN RAISE EXCEPTION 'Visualization scene ID collision or later edit'; END IF;
  IF EXISTS(SELECT 1 FROM visualization_payload p CROSS JOIN LATERAL jsonb_array_elements(p.item->'questions') q
    JOIN speed_reading.visualization_questions r ON r.id=(q->>'id')::uuid
    WHERE r.scene_id<>(p.item->>'id')::uuid OR r.question_text IS DISTINCT FROM q->>'questionText'
      OR r.options_json IS DISTINCT FROM q->'options' OR r.correct_answer IS DISTINCT FROM q->>'correctAnswer'
      OR r.question_type IS DISTINCT FROM q->>'questionType' OR r.display_order<>(q->>'displayOrder')::int
      OR r.hint_text IS NOT NULL OR r.is_deleted)
    THEN RAISE EXCEPTION 'Visualization question ID collision or later edit'; END IF;
END $$;
INSERT INTO speed_reading.visualization_scenes
  (id,exercise_id,description,image_url,duration,display_order,difficulty_level,target_age_group_id,mode,is_deleted,created_at,created_by,version)
SELECT (item->>'id')::uuid,(item->>'exerciseId')::uuid,item->>'description',NULL,(item->>'duration')::int,
  (item->>'displayOrder')::int,(item->>'difficultyLevel')::int,(item->>'targetAgeGroupId')::uuid,
  'assessment',false,now(),'content-pack:visualization-v2',0 FROM visualization_payload
ON CONFLICT (id) DO NOTHING;
INSERT INTO speed_reading.visualization_questions
  (id,scene_id,question_text,options_json,correct_answer,question_type,display_order,is_deleted,created_at,created_by,version)
SELECT (q->>'id')::uuid,(p.item->>'id')::uuid,q->>'questionText',q->'options',q->>'correctAnswer',
  q->>'questionType',(q->>'displayOrder')::int,false,now(),'content-pack:visualization-v2',0
FROM visualization_payload p CROSS JOIN LATERAL jsonb_array_elements(p.item->'questions') q
ON CONFLICT (id) DO NOTHING;
DO $$ BEGIN
  IF (SELECT count(*) FROM visualization_payload p JOIN speed_reading.visualization_scenes s
      ON s.id=(p.item->>'id')::uuid WHERE NOT s.is_deleted)<>120
    OR (SELECT count(*) FROM visualization_payload p JOIN speed_reading.visualization_questions q
      ON q.scene_id=(p.item->>'id')::uuid WHERE NOT q.is_deleted)<>360
    THEN RAISE EXCEPTION 'Visualization insertion incomplete or unexpected questions'; END IF;
END $$;
UPDATE speed_reading.visualization_scenes s SET is_deleted=true,deleted_at=now(),deleted_by='content-pack:visualization-v2'
FROM visualization_baseline b WHERE s.id=(b.item->>'id')::uuid AND NOT s.is_deleted;
COMMIT;
